```javascript
const axios = require("axios");

async function sendOtp(phoneNumber) {
  try {
    const response = await axios.post(
      "https://customer.flip.id/web/user-auth/api/v3.1/otp",
      {
        credential: phoneNumber,
        channel: "via-wa-by-service",
        type: 12,
        device_identifier: "9542a760-6dc1-4650-9aa8-8a5f0e7fc761",
        phone_number: phoneNumber
      },
      {
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..8kxJm0k5kl6xKinwYStpN8x_JU_AVHzUP7JCFjMlTBo",
          "x-internal-api-key": "VlhObGNsQnliMlpwYkdWQmJtUkJkWFJvWlc1MGFXTmhkR2x2YmxObGNuWnBZMlU2T1RBNQ==",
          "Accept": "application/json, text/plain, */*",
          "Accept-Language": "id-ID",
          "Content-Language": "id-ID"
        }
      }
    );

    return response.data;
  } catch (error) {
    if (error.response) {
      return {
        code: error.response.data.code,
        message: error.response.data.message
      };
    } else {
      return {
        error: error.message
      };
    }
  }
}

const phoneNumberToVerify = "+628319193958";

sendOtp(phoneNumberToVerify)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
